package com.nextcandle.ai;
import java.util.*;
public final class FeatureEngine {
 public FeatureVector extract(List<Candle> c){ FeatureVector f=new FeatureVector(); if(c==null||c.size()<5)return f; int n=c.size(); Candle last=c.get(n-1); double[]cl=new double[n],rg=new double[n],bd=new double[n]; for(int i=0;i<n;i++){cl[i]=c.get(i).close;rg[i]=c.get(i).range();bd[i]=c.get(i).body();} double mr=Math.max(1e-9,Maths.mean(rg)), mb=Math.max(1e-9,Maths.meanAbs(bd)); f.set(0,last.body()/mr); f.set(1,last.upperWick()/mr); f.set(2,last.lowerWick()/mr); f.set(3,last.closePosition()*2-1); f.set(4,last.range()/mr-1); f.set(5,last.bodyAbs()/mb-1); f.set(6,(last.close-cl[n-4])/mr); f.set(7,(last.close-cl[Math.max(0,n-7)])/mr); double m5=meanLast(cl,5),m10=meanLast(cl,10); f.set(8,(last.close-m5)/mr); f.set(9,(m5-m10)/mr); f.set(10,slope(cl,5)/mr); f.set(11,slope(cl,10)/mr); double[]last5=Arrays.copyOfRange(rg,Math.max(0,n-5),n),prev5=Arrays.copyOfRange(rg,Math.max(0,n-10),Math.max(0,n-5)); f.set(12,Maths.mean(last5)/Math.max(1e-9,Maths.mean(prev5))-1); double hh=Double.NEGATIVE_INFINITY,ll=Double.POSITIVE_INFINITY; for(int i=0;i<n-1;i++){hh=Math.max(hh,c.get(i).high);ll=Math.min(ll,c.get(i).low);} f.set(13,(last.close-hh)/mr);f.set(14,(last.close-ll)/mr);f.set(15,last.low<ll&&last.close>ll?1:0);f.set(16,last.high>hh&&last.close<hh?1:0); if(n>=2){Candle p=c.get(n-2);boolean be=last.bullish()&&p.bearish()&&last.open<=p.close&&last.close>=p.open;boolean se=last.bearish()&&p.bullish()&&last.open>=p.close&&last.close<=p.open;f.set(17,be?1:(se?-1:0));} f.set(18,(last.lowerWick()-last.upperWick())/mr); int streak=0;boolean dir=last.bullish();for(int i=n-1;i>=0;i--){if(c.get(i).bullish()==dir&&c.get(i).bodyAbs()>0)streak++;else break;} f.set(19,dir?streak/5.0:-streak/5.0);f.set(20,(last.range()-Maths.mean(last5))/mr);f.set(21,rsi(cl,10)/50-1);f.set(22,Maths.clamp((slope(cl,5)/mr)*3,-1,1));f.set(23,Maths.clamp((slope(cl,10)/mr)*3,-1,1));f.set(24,(last.close-m10)/mr);f.set(25,Maths.stdev(last5)/mr);f.set(26,n>=3?((cl[n-1]-cl[n-2])-(cl[n-2]-cl[n-3]))/mr:0);f.set(27,Math.min(1,c.size()/15.0));return f; }
 private static double meanLast(double[]a,int k){int s=Math.max(0,a.length-k);return Maths.mean(Arrays.copyOfRange(a,s,a.length));}
 private static double slope(double[]a,int k){k=Math.min(k,a.length);if(k<2)return 0;int s=a.length-k;double sx=0,sy=0,sxx=0,sxy=0;for(int i=0;i<k;i++){double x=i,y=a[s+i];sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;}double d=k*sxx-sx*sx;return d==0?0:(k*sxy-sx*sy)/d;}
 private static double rsi(double[]a,int p){if(a.length<2)return 50;int s=Math.max(1,a.length-p);double g=0,l=0;for(int i=s;i<a.length;i++){double d=a[i]-a[i-1];if(d>0)g+=d;else l-=d;}if(l==0)return 100;return 100-(100/(1+g/l));}
}
